          hr: 'Pašticada je bogato, mekano goveđe jelo s umakom koji nosi slatko-kiselu i začinsku dubinu. U Dalmaciji se često jede s njokima ili tjesteninom, pa je više izbor za puniji obrok nego za lagani zalogaj.',
          en: 'Pašticada is a rich, tender beef dish with a sauce that brings sweet-sour and spiced depth. In Dalmatia it is often eaten with gnocchi or pasta, so it suits a fuller meal more than a light bite.',
          de: 'Pašticada ist ein kräftiges, zartes Rindfleischgericht mit einer Sauce, die süß-saure und würzige Tiefe bringt. In Dalmatien wird es oft mit Gnocchi oder Pasta gegessen und passt daher eher zu einer volleren Mahlzeit als zu einem leichten Bissen.',
          sv: 'Pašticada är en rik, mör nötköttsrätt med en sås som ger söt-syrlig och kryddig djup. I Dalmatien äts den ofta med gnocchi eller pasta, så den passar bättre som en fylligare måltid än som ett lätt bett.',
          fi: 'Pašticada on täyteläinen, murea naudanliharuoka, jonka kastikkeessa on makeanhapanta ja mausteista syvyyttä. Dalmatiassa sitä syödään usein gnocchien tai pastan kanssa, joten se sopii paremmin täyttäväksi ateriaksi kuin kevyeksi suupalaksi.',
          no: 'Pašticada er en rik, mør okserett med saus som gir søt-syrlig og krydret dybde. I Dalmatia spises den ofte med gnocchi eller pasta, så den passer bedre som et fyldigere måltid enn som en lett bit.',
          pl: 'Pašticada to bogate, miękkie danie wołowe z sosem o słodko-kwaśnej i korzennej głębi. W Dalmacji często je się ją z gnocchi albo makaronem, więc pasuje raczej do pełniejszego posiłku niż lekkiej przekąski.',
